import csv

from src.services.BaseService import BaseService
from src.services.formatters.CashflowFormatter import CashflowFormatter

class CashflowService(BaseService):
    def __init__(self):
        super().__init__()
        self.formatter = CashflowFormatter()

    def get_cashflow(self, year, group_by):
        sql = self.sql_generator.select_cashflow(year, group_by)

        values = self.db.select(sql)

        return self.formatter.format_cashflow(values)

    def export_cashflow(self, file_name, header, rows):
        # Same format as the cashflow_sum.csv generated by the old cashflow.py script
        with open(file_name, "w", encoding="utf-8", newline="") as f:
            writer = csv.writer(f, delimiter="\t", lineterminator="\n")

            writer.writerow(header)

            for row in rows:
                writer.writerow([ row[0] ] + [ "" if amount is None else f"{amount:.2f}" for amount in row[1:] ])
